+            return get(0);
+        }
+
+        public double getX() {
+            return getValue().getX();
+        }
+
+        public double[] getXs() {
+            double[] xs = new double[size()];
+            for (int i = 0; i < size(); i++) {
+                xs[i] = get(i).getX();
+            }
+            return xs;
+        }
+
+        public double[] getYs() {
+            double[] ys = new double[size()];
+            for (int i = 0; i < size(); i++) {
+                ys[i] = get(i).getY();
