+                w.addDocument(document);
+                double newMVx = (multiVal[0].getX() + multiVal[1].getX()) / 2d;
+                double newMVy = (multiVal[0].getY() + multiVal[1].getY()) / 2d;
+                expectedCentroid = expectedCentroid.reset(
