+                } else {
+                    CartesianPoint newCentroid = new CartesianPoint(centroid);
+                    if (randomBoolean()) {
+                        mutateCoordinate(centroid::getY, newCentroid::resetY);
+                    } else {
+                        mutateCoordinate(centroid::getX, newCentroid::resetX);
+                    }
