+            iw.commit();
+            try (IndexReader reader = iw.getReader()) {
+                final Query testQuery = new FieldExistsQuery("text");
+                int hitCount = TopDocsCollectorContext.shortcutTotalHitCount(reader, testQuery);
+                assertEquals(-1, hitCount);
+            }
+        }
+    }
